    case AdminOrderControlState.frozen:
      throw MobileApiException(
        code: 'order_frozen',
        orderTitle: orderTitle,
        message: 'Buyurtma muzlatilgan. Iltimos, adminga xabar bering va buyurtmani muzdan ochishini so‘rang.',
      );
    case AdminOrderControlState.freezeRequested:
      throw const MobileApiException(
        code: 'order_freeze_requested',
        message: 'Buyurtmani muzlatish so‘ralgan. Yangi ish boshlash mumkin emas. Iltimos, adminga murojaat qiling.',
      );
    case AdminOrderControlState.active:
      return;
  }
}

